import Foundation

/// Seconds since the capture session started, read off a monotonic source. Card
/// taps and laugh events are both stamped with one, so their interleaving stays
/// well defined across a wall-clock change (requirement 4.4).
public struct CaptureTime: Codable, Equatable, Comparable, Sendable {
    public var seconds: TimeInterval

    public init(_ seconds: TimeInterval) {
        self.seconds = seconds
    }

    public static func < (lhs: CaptureTime, rhs: CaptureTime) -> Bool {
        lhs.seconds < rhs.seconds
    }
}

/// Anything the timeline can order.
public protocol CaptureTimed {
    var at: CaptureTime { get }
}

/// Which detector produced a laugh event. Scores from different detectors are
/// not comparable until a calibration pass exists (decision D3), so the event
/// carries its source rather than defaulting to one.
public enum LaughDetector: String, Codable, Sendable {
    /// On-device SoundAnalysis, live during the set.
    case soundAnalysis
    /// The batch detector in the Phase B pipeline.
    case batch
}

/// A classified span of audience noise.
public struct LaughEvent: Codable, Equatable, Sendable, CaptureTimed {
    public enum Kind: String, Codable, Sendable { case laughter, applause, cheering }

    public var at: CaptureTime
    public var duration: TimeInterval
    public var kind: Kind
    /// The classifier's confidence in `kind`, 0...1.
    public var confidence: Double
    /// Loudness inside the classified window, 0...1.
    public var intensity: Double
    public var detector: LaughDetector

    public init(
        at: CaptureTime,
        duration: TimeInterval,
        kind: Kind,
        confidence: Double,
        intensity: Double,
        detector: LaughDetector
    ) {
        self.at = at
        self.duration = duration
        self.kind = kind
        self.confidence = confidence
        self.intensity = intensity
        self.detector = detector
    }
}

/// How a segment's boundary was decided. Provenance is kept because Phase B
/// proposes boundaries a comedian never tapped.
public enum SegmentProvenance: String, Codable, Sendable {
    case manual
    case detected
}

/// A span of a show's recording bound to a joke. `end` is absent while the
/// segment is still open — absent, never a zero.
public struct Segment: Identifiable, Codable, Equatable, Sendable {
    public var id: UUID
    public var jokeID: UUID
    public var start: CaptureTime
    public var end: CaptureTime?
    public var provenance: SegmentProvenance

    public init(
        id: UUID = UUID(),
        jokeID: UUID,
        start: CaptureTime,
        end: CaptureTime? = nil,
        provenance: SegmentProvenance
    ) {
        self.id = id
        self.jokeID = jokeID
        self.start = start
        self.end = end
        self.provenance = provenance
    }

    public var duration: TimeInterval? {
        end.map { $0.seconds - start.seconds }
    }
}

/// A card tap, stamped on the capture clock.
public struct TapEvent: Codable, Equatable, Sendable, CaptureTimed {
    public var at: CaptureTime
    public var jokeID: UUID

    public init(at: CaptureTime, jokeID: UUID) {
        self.at = at
        self.jokeID = jokeID
    }
}

/// One ordering over everything the session recorded.
public enum TimelineEntry: Equatable, Sendable, CaptureTimed {
    case tap(TapEvent)
    case laugh(LaughEvent)

    public var at: CaptureTime {
        switch self {
        case .tap(let event): return event.at
        case .laugh(let event): return event.at
        }
    }
}

/// Taps and laugh events merged onto the one clock they share. Equal stamps
/// keep taps first: a tap is the boundary the laughs after it belong to.
public func timeline(taps: [TapEvent], laughs: [LaughEvent]) -> [TimelineEntry] {
    let entries = taps.map(TimelineEntry.tap) + laughs.map(TimelineEntry.laugh)
    return entries.enumerated().sorted { lhs, rhs in
        if lhs.element.at != rhs.element.at {
            return lhs.element.at < rhs.element.at
        }
        if lhs.element.isTap != rhs.element.isTap {
            return lhs.element.isTap
        }
        return lhs.offset < rhs.offset
    }.map { $0.element }
}

extension TimelineEntry {
    var isTap: Bool {
        if case .tap = self { return true }
        return false
    }
}
import Foundation

/// The recording session the coordinator drives. The shipping implementation
/// wraps AVAudioEngine; the requirement cases drive a fake, so what they prove
/// is that this code *asks* for the right thing, never that the platform
/// performs it.
public protocol RecordingSession: AnyObject {
    /// Seconds of audio captured so far — the monotonic source both card taps
    /// and laugh events are stamped against.
    var captured: TimeInterval { get }
    var isRunning: Bool { get }
    func start(writingTo url: URL) throws
    func stop() throws
}

/// Owns the recording for one show: when it runs, where its audio goes, and the
/// clock everything else timestamps against.
public final class CaptureCoordinator {
    /// The container the recording is written inside. Everything here is
    /// deleted when the user deletes the app.
    public let container: URL
    private let session: RecordingSession
    /// One file per uninterrupted stretch of recording. A show with no
    /// interruption has exactly one.
    public private(set) var parts: [URL] = []
    public private(set) var showID: UUID?

    public init(session: RecordingSession, container: URL) {
        self.session = session
        self.container = container
    }

    public var isRecording: Bool { session.isRunning }

    /// The instant to stamp a card tap or a laugh event with.
    public var now: CaptureTime { CaptureTime(session.captured) }

    public func startShow(_ showID: UUID) throws {
        self.showID = showID
        parts = []
        try startPart()
    }

    /// The audio session was taken away — a call, another app. The stretch so
    /// far is closed rather than abandoned.
    public func interruptionBegan() throws {
        guard session.isRunning else { return }
        try session.stop()
    }

    /// The audio session came back. The show continues into a new stretch; the
    /// clock never rewinds, so timestamps stay comparable across the gap.
    public func interruptionEnded() throws {
        guard showID != nil, !session.isRunning else { return }
        try startPart()
    }

    /// Ends the show and hands back its audio, in order.
    @discardableResult
    public func endShow() throws -> [URL] {
        if session.isRunning { try session.stop() }
        showID = nil
        return parts
    }

    private func startPart() throws {
        guard let showID else { return }
        // AAC in an MPEG-4 container: the format the architecture's ~60 MB
        // hour is sized for.
        let url = container
            .appendingPathComponent("shows/\(showID.uuidString)")
            .appendingPathComponent("part-\(parts.count).m4a")
        try session.start(writingTo: url)
        parts.append(url)
    }
}
import Foundation

/// Where the library lives between launches. Phase A keeps everything on the
/// iPad, so the only implementation writes a file inside the app's own
/// container — a location the user can delete by deleting the app.
public protocol LibraryStore {
    func load() throws -> Library
    func save(_ library: Library) throws
}

public struct FileLibraryStore: LibraryStore {
    public let url: URL

    public init(url: URL) {
        self.url = url
    }

    /// The store's home inside a container directory. Named, not defaulted, so
    /// a caller cannot accidentally write outside the container.
    public static func inContainer(_ container: URL) -> FileLibraryStore {
        FileLibraryStore(url: container.appendingPathComponent("library.json"))
    }

    public func load() throws -> Library {
        guard FileManager.default.fileExists(atPath: url.path) else { return Library() }
        return try JSONDecoder().decode(Library.self, from: Data(contentsOf: url))
    }

    public func save(_ library: Library) throws {
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        let data = try JSONEncoder().encode(library)
        // Atomic: a set half-written while the app is killed on stage would
        // lose the material, and material loss is the one unforgivable bug.
        try data.write(to: url, options: .atomic)
    }
}

